messages.content:
Game edukasi Endless Runner tentang membedakan barang konsumsi dan barang modal, dengan tema Clean Modern dan mode Santai. Saya asumsikan rintangan berupa peti kemas dan tumpukan kardus yang bisa dilompati, serta target kategori berganti setiap 5 item benar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "konsumsi-modal-run", title: "Konsumsi vs Modal Run", seed: "konsumsi-modal-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ekonomi",
    concept: "Perbedaan barang konsumsi dan barang modal berdasarkan fungsinya",
    objectives: [
      "Mengelompokkan benda sebagai barang konsumsi atau barang modal",
      "Menjelaskan alasan suatu benda termasuk barang konsumsi atau modal"
    ],
    misconceptions: [
      "Semua benda mahal dianggap barang modal"
    ],
    mode: "category",
    categories: [
      { id: "konsumsi", label: "Barang Konsumsi", color: "#2F80ED" },
      { id: "modal",    label: "Barang Modal",    color: "#E5A100" }
    ],
    items: [
      { id: "nasi",          label: "Nasi",             category: "konsumsi", explain: "Makanan pokok yang langsung dikonsumsi untuk memenuhi kebutuhan." },
      { id: "sepatu",        label: "Sepatu",           category: "konsumsi", explain: "Dipakai pribadi untuk melindungi kaki, bukan untuk produksi." },
      { id: "sabun",         label: "Sabun",            category: "konsumsi", explain: "Dipakai langsung untuk kebersihan diri, habis sekali pakai." },
      { id: "kulkas-rumah",  label: "Kulkas rumah tangga", category: "konsumsi", explain: "Meski mahal, dipakai keluarga untuk menyimpan makanan, bukan produksi." },
      { id: "mesin-jahit",   label: "Mesin jahit",      category: "modal",    explain: "Alat produksi untuk membuat pakaian yang akan dijual." },
      { id: "traktor",       label: "Traktor",          category: "modal",    explain: "Dipakai mengolah lahan pertanian untuk menghasilkan panen." },
      { id: "oven-pabrik",   label: "Oven pabrik",      category: "modal",    explain: "Alat produksi roti dalam jumlah besar untuk dijual." },
      { id: "bor-listrik",   label: "Bor listrik",      category: "modal",    explain: "Alat kerja untuk merakit atau memperbaiki barang produksi." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "peti-kemas", w: 100, h: 44, weight: 3 },
      { type: "hazard", id: "tumpukan-kardus", w: 80, h: 70, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```
